475:  async downloadBackupPlain(force: boolean = false): Promise<WebDavBackupPlainResult> {
476:    const missing = this.requireConfigured();
477:    if (missing !== null) return new WebDavBackupPlainResult(missing, '');
478:
479:    this.status = WebDavSyncStatus.RESTORING;
480:    try {
481:      const client = this.createClient();
482:      const preflight = await this.preflightRemoteRoot(client);
483:      if (preflight !== null) {
484:        this.status = WebDavSyncStatus.ERROR;
485:        return new WebDavBackupPlainResult(preflight, '');
486:      }
487:
488:      const result = await this.backupManager.downloadBackupPlain(
489:        client,
490:        this.settings,
491:        this.manifest,
492:        this.backupFilePath(),
493:        this.legacyBackupFilePath(),
494:        force
495:      );
496:      
497:      this.status = result.result.success ? WebDavSyncStatus.IDLE : WebDavSyncStatus.ERROR;
498:      return result;
499:    } catch (e) {
500:      this.status = WebDavSyncStatus.ERROR;
501:      const msg = e instanceof Error ? e.message : String(e);
502:      return new WebDavBackupPlainResult(WebDavSyncResult.fail('下载失败', msg), '');
503:    }
504:  }
