506:  async importPlainBackup(plain: string): Promise<WebDavSyncResult> {
507:    this.status = WebDavSyncStatus.RESTORING;
508:    const result = await this.backupManager.importPlainBackup(plain);
509:    this.status = result.success ? WebDavSyncStatus.IDLE : WebDavSyncStatus.ERROR;
510:    return result;
511:  }
